package com.ledgerguard.entity; public enum TransactionStatus { PENDING, SUCCESS, FAILED, ROLLED_BACK; public boolean isTerminal() { return this == FAILED || this == ROLLED_BACK; } public boolean canTransitionTo(TransactionStatus target) { if (target == null) return false; if (this == PENDING) return target == SUCCESS || target == FAILED || target == ROLLED_BACK; if (this == SUCCESS) return target == ROLLED_BACK; return false; } }